#include <stdbool.h>
#include <stdio.h>

void ePrimo(void) {
    int n = 0;
    scanf("%d", &n);

    bool primo = true;

    for (int d = 2; d <= n - 1; d++) {
        if (n % d == 0) {
            primo = false;
            break;
        }
    }

    printf("%d\n", primo);
}
